34: std::vector<std::string> ReadFilePaths() {
35:     auto result = std::vector<std::string>();
36: 
37:     ClipboardScope clipboard_scope;
38:     if (!clipboard_scope.IsValid()) {
39:         return result;
40:     }
41: 
42:     HDROP drop_files_handle = (HDROP)GetClipboardData(CF_HDROP);
43:     if (!drop_files_handle) {
44:         return result;
45:     }
46: 
47:     UINT file_count = DragQueryFileW(drop_files_handle, 0xFFFFFFFF, NULL, 0);
48:     result.reserve(file_count);
49:     for (UINT i = 0; i < file_count; ++i) {
50:         UINT path_len = DragQueryFileW(drop_files_handle, i, NULL, 0);
51:         UINT buffer_len = path_len + 1;
52:         std::unique_ptr<WCHAR[]> buffer(new WCHAR[buffer_len]);
53:         path_len = DragQueryFileW(drop_files_handle, i, buffer.get(), buffer_len);
54:         result.emplace_back(Utf16CStringToUtf8String(buffer.get(), path_len));
55:     }
56: 
57:     return result;
58: }
59: 
60: std::wstring Utf8StringToUtf16String(const std::string &input) {
61:     int target_len = MultiByteToWideChar(CP_UTF8, 0, input.c_str(), input.size(), NULL, 0);
62:     std::wstring result(target_len, L'\0');
63:     MultiByteToWideChar(CP_UTF8, 0, input.c_str(), input.size(), result.data(), target_len);
64:     return result;
65: }
66: 
67: std::wstring LongPathToShort(const std::wstring &long_path) {
68:     const WCHAR *prefix = L"\\\\?\\";
69:     std::wstring prefixed_long_path = prefix + long_path;
70:     DWORD buffer_size = GetShortPathNameW(prefixed_long_path.c_str(), NULL, 0);
71:     auto buffer_pointer = std::unique_ptr<WCHAR[]>(new WCHAR[buffer_size]);
72:     GetShortPathNameW(prefixed_long_path.c_str(), buffer_pointer.get(), buffer_size);
73:     size_t offset = wcslen(prefix);
74:     return buffer_pointer.get() + offset;
75: }
76: 
77: void WriteFilePaths(const std::vector<std::string> &file_paths) {
78:     std::vector<std::wstring> file_paths_unicode;
79:     file_paths_unicode.reserve(file_paths.size());
80:     for (auto p = file_paths.cbegin(); p != file_paths.cend(); ++p) {
81:         std::wstring path_unicode = Utf8StringToUtf16String(*p);
82:         if (path_unicode.size() > MAX_PATH) {
83:             path_unicode = LongPathToShort(path_unicode);
84:         }
85:         file_paths_unicode.emplace_back(path_unicode);
86:     }
87: 
88:     // size of DROPFILES structure followed by file paths in double null-terminated string
89:     SIZE_T structure_size_in_bytes = sizeof(DROPFILES);
90:     for (auto p = file_paths_unicode.cbegin(); p != file_paths_unicode.cend(); ++p) {
91:         structure_size_in_bytes += (p->size() + 1) * sizeof(WCHAR);
92:     }
93:     structure_size_in_bytes += sizeof(WCHAR);
94: 
95:     HANDLE data_handle = GlobalAlloc(GMEM_MOVEABLE, structure_size_in_bytes);
96:     if (!data_handle) {
97:         return;
98:     }
99: 
100:     BYTE *data_pointer = static_cast<BYTE *>(GlobalLock(data_handle));
101:     if (!data_pointer) {
102:         return;
103:     }
104: 
105:     DROPFILES *drop_files_pointer = reinterpret_cast<DROPFILES *>(data_pointer);
106:     drop_files_pointer->pFiles = sizeof(DROPFILES);
107:     drop_files_pointer->fWide = TRUE;
108: 
109:     SIZE_T current_offset_in_bytes = sizeof(DROPFILES);
110:     for (auto p = file_paths_unicode.cbegin(); p != file_paths_unicode.cend(); ++p) {
111:         WCHAR *target_path = reinterpret_cast<WCHAR *>(data_pointer + current_offset_in_bytes);
112:         SIZE_T offset_in_chars = p->size() + 1;
113:         SIZE_T offset_in_bytes = offset_in_chars * sizeof(WCHAR);
114:         memcpy(target_path, p->c_str(), offset_in_bytes);
115:         current_offset_in_bytes += offset_in_bytes;
116:     }
117: 
118:     WCHAR *tail = reinterpret_cast<WCHAR *>(data_pointer + current_offset_in_bytes);
119:     *tail = L'\0';
120: 
121:     GlobalUnlock(data_handle);
122: 
123:     ClipboardScope clipboard_scope;
124:     if (!clipboard_scope.IsValid()) {
125:         GlobalFree(data_handle);
126:         return;
127:     }
128: 
129:     EmptyClipboard();
130: 
131:     if (!SetClipboardData(CF_HDROP, data_handle)) {
132:         GlobalFree(data_handle);
133:         return;
134:     }
135: }
136: 
137: void ClearClipboard() {
138:     ClipboardScope clipboard_scope;
139:     if (!clipboard_scope.IsValid()) {
140:         return;
141:     }
142: 
143:     EmptyClipboard();
144: }
