172: bool GetEncoderClsid(const WCHAR *format, CLSID *pClsid)
173: {
174:     UINT  num = 0;          // number of image encoders
175:     UINT  size = 0;         // size of the image encoder array in bytes
176: 
177:     GetImageEncodersSize(&num, &size);
178:     if (size == 0) {
179:         return false;
180:     }
181: 
182:     std::unique_ptr<ImageCodecInfo, FreeDeleter> pImageCodecInfo((ImageCodecInfo*)(malloc(size)));
183:     if (!pImageCodecInfo) {
184:         return false;
185:     }
186: 
187:     if (GetImageEncoders(num, size, pImageCodecInfo.get()) != Ok) {
188:         return false;
189:     }
190: 
191:     for (UINT j = 0; j < num; ++j)
192:     {
193:         if (wcscmp(pImageCodecInfo.get()[j].MimeType, format) == 0)
194:         {
195:             *pClsid = pImageCodecInfo.get()[j].Clsid;
196:             return true;
197:         }
198:     }
199: 
200:     return false;
201: }
