203: bool SaveBitmapAsJpeg(HBITMAP hBmp, LPCWSTR lpszFilename, ULONG uQuality)
204: {
205:     GdiplusScope gdiplus_scope;
206:     if (!gdiplus_scope.IsValid()) {
207:         return false;
208:     }
209: 
210:     std::unique_ptr<Bitmap> pBitmap(new Bitmap(hBmp, NULL));
211: 
212:     CLSID imageCLSID;
213:     GetEncoderClsid(L"image/jpeg", &imageCLSID);
214: 
215:     EncoderParameters encoderParams;
216:     encoderParams.Count = 1;
217:     encoderParams.Parameter[0].NumberOfValues = 1;
218:     encoderParams.Parameter[0].Guid = EncoderQuality;
219:     encoderParams.Parameter[0].Type = EncoderParameterValueTypeLong;
220:     encoderParams.Parameter[0].Value = &uQuality;
221: 
222:     Status result = pBitmap->Save(lpszFilename, &imageCLSID, &encoderParams);
223: 
224:     return result == Ok;
225: }
