227: bool SaveBitmapAsPng(HBITMAP hBmp, LPCWSTR lpszFilename)
228: {
229:     GdiplusScope gdiplus_scope;
230:     if (!gdiplus_scope.IsValid()) {
231:         return false;
232:     }
233: 
234:     std::unique_ptr<Bitmap> pBitmap(new Bitmap(hBmp, NULL));
235: 
