245: bool SaveClipboardImageAsJpeg(const std::string &target_path, float compression_factor) {
246:     ClipboardScope clipboard_scope;
247:     if (!clipboard_scope.IsValid()) {
248:         return false;
249:     }
250: 
251:     HBITMAP image_handle = (HBITMAP)GetClipboardData(CF_BITMAP);
252:     if (!image_handle) {
253:         return false;
254:     }
255: 
256:     std::wstring target_path_unicode = Utf8StringToUtf16String(target_path);
257:     ULONG quality = (ULONG)(compression_factor * 100);
258:     return SaveBitmapAsJpeg(image_handle, target_path_unicode.c_str(), quality);
259: }
