261: bool SaveClipboardImageAsPng(const std::string &target_path) {
262:     ClipboardScope clipboard_scope;
263:     if (!clipboard_scope.IsValid()) {
264:         return false;
265:     }
266: 
267:     HBITMAP image_handle = (HBITMAP)GetClipboardData(CF_BITMAP);
268:     if (!image_handle) {
269:         return false;
270:     }
271: 
272:     std::wstring target_path_unicode = Utf8StringToUtf16String(target_path);
273:     return SaveBitmapAsPng(image_handle, target_path_unicode.c_str());
274: }
