276: bool PutImageIntoClipboard(const std::string &image_path) {
277:     GdiplusScope gdiplus_scope;
278:     if (!gdiplus_scope.IsValid()) {
279:         return false;
280:     }
281: 
282:     std::wstring image_path_unicode = Utf8StringToUtf16String(image_path);
283:     std::unique_ptr<Bitmap> pImage(new Bitmap(image_path_unicode.c_str()));
284:     HBITMAP handle;
285: 
286:     if (pImage->GetHBITMAP(Color::White, &handle) != Ok) {
287:         return false;
288:     }
289: 
290:     BITMAP bm;
291:     GetObject(handle, sizeof bm, &bm);
292:     BITMAPINFOHEADER bi = { sizeof bi, bm.bmWidth, bm.bmHeight, 1, bm.bmBitsPixel, BI_RGB };
293: 
294:     std::vector<BYTE> vec(bm.bmWidthBytes * bm.bmHeight);
295:     auto hdc = GetDC(NULL);
296:     GetDIBits(hdc, handle, 0, bi.biHeight, vec.data(), (BITMAPINFO*)&bi, 0);
297:     ReleaseDC(NULL, hdc);
298: 
299:     auto hmem = GlobalAlloc(GMEM_MOVEABLE, sizeof bi + vec.size());
300:     if (!hmem) {
301:         return false;
302:     }
303: 
304:     auto buffer = (BYTE*)GlobalLock(hmem);
305:     memcpy(buffer, &bi, sizeof bi);
306:     memcpy(buffer + sizeof bi, vec.data(), vec.size());
307:     GlobalUnlock(hmem);
308: 
309:     ClipboardScope clipboard_scope;
310:     if (!clipboard_scope.IsValid()) {
311:         GlobalFree(hmem);
312:         return false;
313:     }
314: 
315:     EmptyClipboard();
316: 
317:     if (!SetClipboardData(CF_DIB, hmem)) {
318:         GlobalFree(hmem);
319:         return false;
320:     }
321: 
322:     return true;
323: }
